from pathlib import Path
import json,html,sys
root=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parent.parent
brands=json.loads((root/'source/brands.json').read_text());directions=json.loads((root/'source/directions.json').read_text())
states={'home':'Arrival','results':'Stay options','rates':'Room & rates','terms':'Terms','photos':'Pictures','location':'Location'}
cards=[]
for n,b in enumerate(brands):
    d=directions[b['id']];pre='previews/'+b['id']+'/'
    home=pre+'home.html' if (root/pre/'home.html').exists() else pre+'home-desktop-design.png'
    buttons=''.join('<button data-screen="'+s+'" aria-pressed="'+str(s=='home').lower()+'">'+label+'</button>' for s,label in states.items())
    cards.append('<article id="'+b['id']+'" data-property="'+b['id']+'" data-home="'+home+'" style="--ink:'+b['ink']+';--accent:'+b['accent']+'"><div class="intro"><p class="eyebrow">0'+str(n+1)+' / '+d['idea']+'</p><h2>'+b['name']+'</h2><p>'+b['positioning']+'</p></div><nav class="screenTabs" aria-label="'+b['name']+' review screens">'+buttons+'</nav><div class="stage"><a class="desktopLink" href="'+home+'" target="_blank"><span>Desktop · 1440px</span><img class="desktopImage" src="'+pre+'home-desktop-design.png" alt="'+b['name']+' desktop arrival"></a><a class="mobileLink" href="'+pre+'home-mobile-design.png" target="_blank"><span>Mobile · 390px</span><img class="mobileImage" src="'+pre+'home-mobile-design.png" alt="'+b['name']+' mobile arrival"></a></div><div class="notes"><p><strong>Arrival</strong> '+d['arrival']+'</p><p><strong>Later screens</strong> '+d['later']+'</p><p><strong>Mobile</strong> '+d['mobile']+'</p><p><strong>Background / reveal</strong> '+d['background']+' '+d['motion']+' Added CSS motion stops for reduced motion; native carousel motion is unchanged.</p><p><strong>Brand evidence</strong> '+b['character']+' '+b['headingFont']+' / '+b['bodyFont']+'. <a href="'+b['url']+'" target="_blank" rel="noopener">Official website ↗</a></p><p class="fixtureNote">Arrival uses the reviewed local home proof. Later screens are authored offline fixtures: no loaded inventory, prices or policy claims.</p><div class="actions"><a class="openScreen" href="'+home+'" target="_blank">Inspect selected screen ↗</a><a href="'+pre+'journey.html?screen=results" target="_blank">Open working later-screen fixture ↗</a><a href="packages/'+b['id']+'-Legacy-BookNow-R2.zip">R2 theme ZIP</a></div></div></article>')
table=''.join('<tr><th scope="row">'+b['name']+'</th><td>'+directions[b['id']]['arrival']+'</td><td>'+directions[b['id']]['later']+'</td><td>'+directions[b['id']]['mobile']+'</td></tr>' for b in brands)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Five distinct booking experiences · R2 review</title><style>
*{box-sizing:border-box}body{margin:0;background:#efefe7;color:#283327;font:15px/1.7 Arial,sans-serif}a{color:inherit;text-underline-offset:4px}header{padding:55px max(24px,calc((100vw - 1260px)/2));background:#20291f;color:#f5f4e8;border-top:7px solid #ad9665}h1{font:normal clamp(38px,5vw,67px)/1.1 Georgia,serif;max-width:900px;margin:16px 0 24px}header p{max-width:850px}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:.16em}main{max-width:1310px;margin:auto;padding:28px 24px}aside{background:#e0e5d7;border:1px solid #bac3b0;padding:24px;margin:12px 0 38px}aside p{max-width:1100px}header nav{display:flex;gap:12px 24px;flex-wrap:wrap;margin-top:25px}header nav a{font-size:13px}.comparison{overflow:auto;margin:20px 0 38px}table{border-collapse:collapse;min-width:850px;width:100%;background:#fbfbf5;font-size:13px}th,td{padding:17px;border:1px solid #c7ccbd;vertical-align:top;text-align:left}thead{background:#dce2d2}article{border:1px solid #c4ccba;border-top:5px solid var(--accent);background:#fbfbf4;margin:0 0 55px;scroll-margin-top:15px}.intro{padding:28px 30px 8px}h2{font:normal 35px/1.2 Georgia,serif;color:var(--ink);margin:8px 0 16px}.screenTabs{display:flex;flex-wrap:wrap;gap:7px;padding:12px 30px 23px}.screenTabs button{min-height:44px;padding:10px 16px;background:transparent;border:1px solid #9eaa91;font:13px Arial,sans-serif;color:#283327;cursor:pointer}.screenTabs button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}.stage{display:grid;grid-template-columns:minmax(0,1fr) 235px;gap:25px;align-items:start;padding:26px 30px;background:#e3e5db}.stage a{min-width:0;text-decoration:none}.stage span{display:block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;margin:0 0 8px}.stage img{width:100%;height:auto;display:block;border:1px solid #bac2b0;box-shadow:0 4px 16px #2631261a}.notes{padding:18px 30px 28px}.notes p{margin:13px 0}.notes strong{display:inline-block;min-width:160px;color:var(--ink)}.actions{display:flex;flex-wrap:wrap;gap:16px 24px;font-size:13px;border-top:1px solid #c4ccba;padding-top:20px;margin-top:20px}.openScreen{font-weight:bold}.fixtureNote{font-size:13px;color:#58624e}.reviewList{padding-left:20px}a:focus-visible,button:focus-visible{outline:3px solid #a5732f;outline-offset:3px}footer{padding:20px 0 40px;font-size:13px}@media(max-width:760px){header{padding:34px 20px}main{padding:18px 14px}.intro,.notes{padding:22px 18px}.screenTabs{padding:10px 18px 20px}.stage{grid-template-columns:1fr;padding:18px}.mobileLink{max-width:300px;margin:auto}.notes strong{display:block}h2{font-size:29px}}
</style></head><body><header><p class="eyebrow">Extraordinary / old BookNow / R2 consolidated creative revision / 25 October 2026</p><h1>The property experience,<br>through every screen.</h1><p>Five themes with different arrival compositions, booking arrangements, backgrounds, native carousel treatments and information layouts—carried through rooms, rates and details. The native booking sequence remains the same.</p><nav>'''+''.join('<a href="#'+b['id']+'">'+b['name']+'</a>' for b in brands)+'''</nav></header><main><aside><strong>Use the six screen tabs under each property.</strong><p>Inspect desktop and mobile together, then open a working later-screen fixture to try View Rates, Terms, Pictures, Location and Close. Those fixtures contain neutral authored content, with no real prices, availability or booking actions.</p><p>The ZIP supports CSS layout, surfaces, existing control styling and brief native page-entry effects. CMS setup supplies accepted marks/photos/captions/copy. Different carousel timing, loading order, asynchronous behaviour or booking steps require vendor support. <a href="CAPABILITIES.md">Read the explicit capability boundary</a>.</p><p><a href="../2026-10-25-r1/index.html">Local R1 review</a> · R1 remains separately recoverable in Git. Nothing is installed.</p></aside><details><summary>Compare the material layout differences</summary><div class="comparison"><table><thead><tr><th>Property</th><th>Arrival & booking</th><th>Results, rates & details</th><th>Mobile presentation</th></tr></thead><tbody>'''+table+'''</tbody></table></div></details>'''+''.join(cards)+'''<aside><strong>Review before installation</strong><ul class="reviewList"><li>Does each design express its own property through composition and information hierarchy?</li><li>Review all six screen tabs and both sizes, not only the arrival image.</li><li>Review the separate CMS photograph/crop/caption and introduction.</li><li>Accept or correct a specific version before a separately authorised installer proceeds.</li></ul><p><a href="INSTALLER.md">Installer / backup / rollback</a> · <a href="README.md">Source / build</a> · <a href="DESIGN.md">Design comparison</a> · <a href="verification-summary.json">Measured checks</a></p></aside><footer>R2 is a review candidate, not a live release. No live CMS edits, availability search, booking, hold or payment. R0 additional spend; included allowance unknown. Native map, carousel accessibility/motion and end-to-end checkout limitations remain open.</footer></main><script>
document.querySelectorAll('article').forEach(card=>{card.querySelectorAll('[data-screen]').forEach(button=>button.addEventListener('click',()=>{const s=button.dataset.screen,p='previews/'+card.dataset.property+'/';card.querySelectorAll('[data-screen]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));card.querySelector('.desktopImage').src=p+s+'-desktop-design.png';card.querySelector('.mobileImage').src=p+s+'-mobile-design.png';const target=s==='home'?card.dataset.home:p+'journey.html?screen='+s;card.querySelector('.desktopLink').href=target;card.querySelector('.mobileLink').href=p+s+'-mobile-design.png';card.querySelector('.openScreen').href=target;card.querySelector('.fixtureNote').textContent=s==='home'?'Arrival uses the reviewed local home proof. Later screens are authored offline fixtures.':'OFFLINE '+s.toUpperCase()+' FIXTURE · neutral authored content, no live inventory, prices, policies or transactions.'}))});
</script></body></html>'''
(root/'index.html').write_text(page,encoding='utf-8');print('Six-screen five-property comparison gallery written.')

